{
 "criticisms": [
  {
   "element": "Wholesaler supply line",
   "quote": "Factory_backlog + Wholesaler_in_transit",
   "kind": "information",
   "why": "The wholesaler does not see inside the factory, yet its supply line reads the factory's backlog directly.",
   "suggestion": "Compute the supply line from the wholesaler's own records, orders placed minus goods received, or show that the two are the same."
  },
  {
   "element": "Wholesaler lead time",
   "quote": "Transit_delay",
   "kind": "constant",
   "why": "The desired supply line uses a fixed lead time equal to the transit delay. When the factory runs short, orders also wait in its backlog, so the real lead time is longer and the target too small.",
   "suggestion": "State the fixed lead time as an assumption, or measure it from the wholesaler's records."
  },
  {
   "element": "Wholesaler indicated orders",
   "quote": "Supply_line_weight * (Wholesaler_desired_supply_line - Wholesaler_supply_line) / Inventory_adjustment_time",
   "kind": "other",
   "why": "The supply line gap is closed over the inventory adjustment time. Managers may correct what they have on order at a different speed from their stock, so one constant does two jobs.",
   "suggestion": "Add a supply line adjustment time, equal at first to the inventory adjustment time, and test it."
  },
  {
   "element": "Wholesaler forecast change",
   "quote": "(Wholesaler_demand_signal - Wholesaler_expected_demand) / Inventory_adjustment_time",
   "kind": "constant",
   "why": "The forecast is smoothed over the inventory adjustment time, so the speed of forecasting and the speed of stock correction cannot be varied separately.",
   "suggestion": "Give the forecast its own demand smoothing time."
  }
 ]
}
